class Solution {
  public int minCostII(int[][] costs) {
    int n = costs.length, k = costs[0].length;
    int[] prev = new int[k];
    for (int i = 0; i < n; i++) {
      // cheapest and second cheapest previous colours: any colour but the cheapest's own can use
      // the cheapest
      int min1 = Integer.MAX_VALUE, min2 = Integer.MAX_VALUE, arg = -1;
      for (int j = 0; j < k; j++) {
        if (prev[j] < min1) {
          min2 = min1;
          min1 = prev[j];
          arg = j;
        } else if (prev[j] < min2) {
          min2 = prev[j];
        }
      }
      int[] cur = new int[k];
      for (int j = 0; j < k; j++) cur[j] = costs[i][j] + (j == arg ? min2 : min1);
      prev = cur;
    }
    int best = Integer.MAX_VALUE;
    for (int v : prev) best = Math.min(best, v);
    return best;
  }
}
